import {
  deepDiff,
  extract,
  formatForPrint,
  parseCommandLine,
  renderError,
  renderHelp
} from './lib/index.mjs';

export function main(argv = process.argv.slice(2)) {
  const parsed = parseCommandLine(argv);

  if (parsed.kind === 'help') {
    process.stdout.write(renderHelp());
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(renderError(parsed.message));
    return 2;
  }

  const { a, b } = parsed.values;
  const obj = {
    users: [
      { name: a, age: b },
      { name: `${a}2`, age: b + 1 }
    ]
  };

  const results = [
    deepDiff(obj, obj),
    extract(obj, "root['users'][0]['name']"),
    extract(obj, "root['users'][1]['age']"),
    deepDiff(obj.users[0], obj.users[1]),
    extract(obj, "root['users'][0]"),
    deepDiff(obj.users, []),
    deepDiff(obj, { users: [] }),
    extract(obj, "root['users']")
  ];

  for (const value of results) {
    console.log(formatForPrint(value));
  }

  return 0;
}

const exitCode = main();
if (exitCode !== 0) {
  process.exit(exitCode);
}

